{
  "ruleset_id": "programma-dopolnitelnogo-obrazovaniya",
  "rules": [
    {
      "description": "Организация должна иметь действующую лицензию на образовательную деятельность.",
      "severity": "critical",
      "category": "license",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Объём программы должен составлять не менее 72 часов.",
      "severity": "critical",
      "category": "curriculum",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Не менее 80% преподавателей должны иметь профильную квалификацию.",
      "severity": "critical",
      "category": "staff",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Допустимый формат реализации программы — только очный или смешанный.",
      "severity": "critical",
      "category": "delivery_format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "subsidy-energy-efficiency",
  "rules": [
    {
      "description": "Проект обязан снизить потребление энергии не менее чем на 20%.",
      "severity": "critical",
      "category": "energy_reduction",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Доля софинансирования заявителя должна составлять не менее 30%.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "К заявке должен быть приложен технический паспорт объекта.",
      "severity": "major",
      "category": "documentation",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Работы должны быть завершены не позднее 31 декабря 2027 года.",
      "severity": "critical",
      "category": "completion_deadline",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "fond-nordstar-main-track-v2-4",
  "rules": [
    {
      "description": "The applicant must have been registered for at least 24 months.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "ge",
        "value": 24
      }
    },
    {
      "description": "The requested grant amount must not exceed 250000 euros.",
      "severity": "critical",
      "category": "request_limit",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "le",
        "value": 250000
      }
    },
    {
      "description": "An independent audit report for the last completed financial year must be attached.",
      "severity": "critical",
      "category": "audit",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The submission date must be no later than 31 March 2027.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "le",
        "value": "2027-03-31"
      }
    },
    {
      "description": "The declared headcount must match the headcount in the annual report.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "field": "org_v2.declared_headcount",
        "op": "consistent",
        "value": {
          "fields": [
            "org_v2.declared_headcount",
            "annual_report.headcount"
          ]
        }
      }
    },
    {
      "description": "The annual report must be prepared in accordance with IFRS.",
      "severity": "minor",
      "category": "reporting_standard",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": true
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grant-program-2026",
  "rules": [
    {
      "description": "The applicant organization must have been registered for at least 12 months on the submission date.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "application_form.months_registered",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "The requested grant amount must not exceed EUR 100,000.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "le",
        "value": 100000
      }
    },
    {
      "description": "Equipment expenses must not exceed 40% of the total budget.",
      "severity": "major",
      "category": "budget_composition",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "le",
        "value": 40
      }
    },
    {
      "description": "The application form must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The detailed budget must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The registration certificate or registry extract must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The latest financial statement must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application must be submitted no later than 1 October 2026.",
      "severity": "major",
      "category": "deadline",
      "condition": {
        "field": "application_form.submission_date",
        "op": "le",
        "value": "2026-10-01"
      }
    },
    {
      "description": "The application form must be signed by the legal representative.",
      "severity": "critical",
      "category": "signature",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The requested amount in the application form must exactly match the total in the detailed budget.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "op": "consistent",
        "fields": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ],
        "value": null
      }
    },
    {
      "description": "The financial statement must cover FY2025.",
      "severity": "minor",
      "category": "reporting_period",
      "condition": {
        "field": "finance_statement.period",
        "op": "eq",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "capital-repair-program",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "building_age",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должны поддержать не менее 66% голосов.",
      "severity": "critical",
      "category": "owner_approval",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов.",
      "severity": "major",
      "category": "defect_report",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 апреля 2027 года включительно.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "medical-device-procurement",
  "rules": [
    {
      "description": "The product must have a medical registration certificate.",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "documents.medical_registration.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "At the delivery date, the product must have at least 12 months of remaining shelf life.",
      "severity": "critical",
      "category": "expiry",
      "condition": {
        "field": "product.expiry_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Products requiring a cold chain must have a cold-chain compliance protocol.",
      "severity": "critical",
      "category": "cold-chain",
      "condition": {
        "field": "documents.cold_chain_protocol.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The product's country of origin must be Russia or a state of the Eurasian Economic Union.",
      "severity": "critical",
      "category": "origin",
      "condition": {
        "field": "product.origin_country",
        "op": "in",
        "value": [
          "Россия",
          "государство ЕАЭС"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "preferential-sme-microloan",
  "rules": [
    {
      "description": "Annual company revenue must not exceed 120,000,000 RUB.",
      "severity": "critical",
      "category": "revenue",
      "condition": {
        "field": "company.annual_revenue_rub",
        "op": "le",
        "value": 120000000
      }
    },
    {
      "description": "The company must have no overdue debt.",
      "severity": "critical",
      "category": "debt",
      "condition": {
        "field": "company.overdue_debt",
        "op": "eq",
        "value": 0
      }
    },
    {
      "description": "At least 51% of the company must be owned by Russian owners.",
      "severity": "critical",
      "category": "ownership",
      "condition": {
        "field": "company.russian_ownership_pct",
        "op": "ge",
        "value": 51
      }
    },
    {
      "description": "The requested loan amount must not exceed 10,000,000 RUB.",
      "severity": "critical",
      "category": "loan_amount",
      "condition": {
        "field": "loan.requested_rub",
        "op": "le",
        "value": 10000000
      }
    }
  ]
}

{
  "ruleset_id": "municipal-subsidy-2026",
  "rules": [
    {
      "description": "The applicant must have been registered for at least 12 months.",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "The requested subsidy must not exceed 5,000,000 RUB.",
      "severity": "critical",
      "category": "amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "The application must include financial statements for the last year.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application must be submitted no later than September 15, 2026, inclusive.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "The organization must have no tax arrears.",
      "severity": "critical",
      "category": "tax_compliance",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "eq",
        "value": 0
      }
    }
  ]
}

{
  "ruleset_id": "repair-works-procurement",
  "rules": [
    {
      "description": "Supplier annual turnover must be at least 10,000,000 rubles.",
      "severity": "critical",
      "category": "financial_eligibility",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "A valid SRO certificate is required for eligibility.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The participant's sanctions screening status must be clear.",
      "severity": "critical",
      "category": "sanctions",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Bids must be submitted no later than November 20, 2026.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "konkurs-prikladnykh-issledovaniy",
  "rules": [
    {
      "description": "Руководитель должен иметь степень «кандидат наук» или «доктор наук».",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": [
          "кандидат наук",
          "доктор наук"
        ]
      }
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Должно быть предоставлено согласие на размещение обезличенных данных исследования.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявленный в форме бюджет должен совпадать с итогом сметы.",
      "severity": "major",
      "category": "budget",
      "condition": {
        "op": "consistent",
        "fields": [
          "application.declared_budget_rub",
          "budget.total_rub"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "social-contract",
  "rules": [
    {
      "description": "The household must be located in Moscow or the Moscow region.",
      "severity": "critical",
      "category": "region",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": [
          "Moscow",
          "Moscow Oblast"
        ]
      }
    },
    {
      "description": "Monthly income per person must not exceed 25,000 rubles.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Consent to the processing of personal data must be present.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The applicant's employment status must be unemployed or a job seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": [
          "unemployed",
          "job_seeker"
        ]
      }
    }
  ]
}
